// Generated by scripts/sync_setup.js from tmdb-catalog.json.
const addresses = {
    "plugin": "https://raw.githubusercontent.com/dr-octagon/Nuvio/main/manifest.json",
    "catalog": "https://catalog.nuvio.tv/%7B%22language%22%3A%22tr-TR%22%2C%22region%22%3A%22TR%22%7D/manifest.json"
};
document.getElementById('catalog-install').href = addresses.catalog.replace(/^https:\/\//, 'nuvio://');
for (const button of document.querySelectorAll('[data-copy]')) {
    button.addEventListener('click', async () => {
        const id = button.dataset.copy, address = addresses[id], status = document.getElementById(id + '-status');
        const destination = id === 'plugin' ? 'plugin / kaynak deposu ekleme' : 'katalog eklentisi ekleme';
        try {
            await navigator.clipboard.writeText(address);
            status.textContent = 'Adres kopyalandı. Nuvio’daki ' + destination + ' bölümüne yapıştır.';
        } catch (_) {
            status.replaceChildren();
            const input = document.createElement('input');
            input.value = address; input.readOnly = true;
            input.setAttribute('aria-label', 'Kopyalanacak ' + id + ' adresi');
            input.style.width = '100%'; status.appendChild(input); input.focus(); input.select();
        }
    });
}
